\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── UNICEF Color Theme ──
\definecolor{primary}{HTML}{0775A6}       % deep UNICEF cyan
\definecolor{secondary}{HTML}{1CABE2}     % bright UNICEF cyan
\definecolor{accent}{HTML}{F2994A}        % warm amber
\definecolor{warm}{HTML}{E76F51}          % coral
\definecolor{bgposter}{HTML}{F2F6FA}      % light airy blue-grey
\definecolor{cyanbg}{HTML}{E8F4FD}
\definecolor{amberbg}{HTML}{FFF8F0}
\definecolor{warmbg}{HTML}{FFF5F3}
\definecolor{cyantitlebg}{HTML}{D6EEF9}
\definecolor{ambertitlebg}{HTML}{FFECD2}
\definecolor{warmtitlebg}{HTML}{FFEAE6}
\definecolor{textdark}{HTML}{17212E}
\definecolor{textgray}{HTML}{4A5568}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=10pt, parsep=2pt, topsep=4pt,
  label={\color{primary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=10pt, parsep=2pt, topsep=4pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  cyancard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cyanbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=cyantitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=amberbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=ambertitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.18},
  },
  warmcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=warmbg,
    borderline west={5pt}{0pt}{warm},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{warm},
    coltitle=warm, colbacktitle=warmtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={warm!50},
    valign=top, drop shadow={opacity=0.18},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=accent!12!white,
    borderline west={6pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=accent,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════════════════
% TITLE BAR — span=2, top to row3
% ═══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=36pt, right=36pt, top=18pt, bottom=14pt,
  halign=center, valign=center,
  drop shadow={opacity=0.35}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{56}{64}\selectfont\bfseries Every Child Deserves\vspace{-4pt}\\ to Learn}\\[14pt]
  {\fontsize{30}{38}\selectfont\color{white!80} UNICEF \textbullet\ Global Education Advocacy \textbullet\ unicef.org/education}
}

% ═══════════════════════════════════════════════════════
% STAT BANNER — The Visual Anchor — span=2, row3 to row7
% ═══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!10!white, boxrule=0pt, arc=0pt,
  left=8pt, right=8pt, top=10pt, bottom=10pt,
  valign=center,
  borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=2, between=row3 and row7}{
  \centering\fontsize{24}{30}\selectfont
  \begin{minipage}[c]{0.32\linewidth}\centering
    \colorbox{primary!15}{\parbox{0.92\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{68}{82}\selectfont\bfseries\color{primary}250\vspace{-6pt}\\ million}\\[8pt]
      {\fontsize{24}{30}\selectfont\color{textdark}\textbf{children \& adolescents}\\[2pt] are out of school worldwide}\vspace{12pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.32\linewidth}\centering
    \colorbox{accent!15}{\parbox{0.92\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{68}{82}\selectfont\bfseries\color{accent}70\%}\\[8pt]
      {\fontsize{24}{30}\selectfont\color{textdark}\textbf{cannot read} a simple\\[2pt] text by age 10}\vspace{12pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.32\linewidth}\centering
    \colorbox{warm!15}{\parbox{0.92\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{68}{82}\selectfont\bfseries\color{warm}190+}\\[8pt]
      {\fontsize{24}{30}\selectfont\color{textdark}\textbf{countries} where\\[2pt] UNICEF delivers education}\vspace{12pt}%
    }}
  \end{minipage}
}

% ═══════════════════════════════════════════════════════
% ROW A: Crisis (col 1) + Barriers (col 2) | row7 to row14
% ═══════════════════════════════════════════════════════
\posterbox[cyancard, title={The Global Education Crisis}
]{name=crisis, column=1, between=row7 and row14}{
  \fontsize{25}{34}\selectfont
  Education is a fundamental right -- yet millions are denied it daily due to conflict, poverty, and systemic failures.

  \vspace{6pt}
  \colorbox{primary!18}{\parbox{0.94\linewidth}{%
    \centering\fontsize{24}{30}\selectfont
    \textbf{Learning Poverty:} 70\% of children in low- and middle-income countries cannot read a simple text by age 10.
  }}

  \vspace{6pt}
  \colorbox{secondary!18}{\parbox{0.94\linewidth}{%
    \centering\fontsize{24}{30}\selectfont
    \textbf{Girls in crisis settings} are \textbf{2.5$\times$ more likely} to be out of school than boys.
  }}

  \vspace{6pt}
  \colorbox{primary!18}{\parbox{0.94\linewidth}{%
    \centering\fontsize{24}{30}\selectfont
    \textbf{Nearly 49\%} of children with disabilities in low-income countries have \textbf{never} set foot in a classroom.
  }}

  \vspace{8pt}
  \fontsize{24}{30}\selectfont\color{textgray}
  Every number represents a child whose potential remains unrealized -- and a community held back from prosperity.
}

\posterbox[ambercard, title={Barriers to Education}
]{name=barriers, column=2, between=row7 and row14}{
  \fontsize{26}{34}\selectfont
  \begin{itemize}[itemsep=14pt]
    \item \textbf{Armed Conflict} \\
    {\fontsize{22}{28}\selectfont\color{textgray} Schools destroyed, teachers displaced, children traumatized. Crisis zones see the highest exclusion rates.}

    \item \textbf{Poverty} \\
    {\fontsize{22}{28}\selectfont\color{textgray} Families cannot afford fees, uniforms, or supplies. Children are forced into labour instead of learning.}

    \item \textbf{Gender Inequality} \\
    {\fontsize{22}{28}\selectfont\color{textgray} Deeply rooted social norms limit girls' access, especially at the secondary level.}

    \item \textbf{Disability} \\
    {\fontsize{22}{28}\selectfont\color{textgray} Nearly half of children with disabilities in low-income countries are excluded from education entirely.}

    \item \textbf{Climate Shocks} \\
    {\fontsize{22}{28}\selectfont\color{textgray} Floods, droughts, and extreme weather increasingly disrupt schooling for the most vulnerable.}
  \end{itemize}
}

% ═══════════════════════════════════════════════════════
% ROW B: UNICEF Focus Areas (col 1) + Call to Action (col 2) | row14 to bottom
% ═══════════════════════════════════════════════════════
\posterbox[cyancard, title={UNICEF's Education Focus Areas}
]{name=focus, column=1, between=row14 and bottom}{
  \fontsize{22}{30}\selectfont
  \setlist[itemize]{leftmargin=16pt, itemsep=8pt, topsep=2pt}
  \begin{itemize}
    \item \textbf{Early Childhood Development} \\
    {\fontsize{20}{26}\selectfont\color{textgray} Pre-primary education and school readiness programmes.}

    \item \textbf{Inclusive Education} \\
    {\fontsize{20}{26}\selectfont\color{textgray} Ensuring children with disabilities and marginalized groups can access and thrive in school.}

    \item \textbf{Gender Equality in Education} \\
    {\fontsize{20}{26}\selectfont\color{textgray} Removing barriers that prevent girls from enrolling, staying in, and completing school.}

    \item \textbf{Education in Emergencies} \\
    {\fontsize{20}{26}\selectfont\color{textgray} Learning continuity for children affected by conflict, displacement, and disasters.}

    \item \textbf{Digital \& Innovative Learning} \\
    {\fontsize{20}{26}\selectfont\color{textgray} Leveraging technology to expand access and improve learning quality.}

    \item \textbf{Adolescent Skills Development} \\
    {\fontsize{20}{26}\selectfont\color{textgray} Equipping young people for employment, civic engagement, and lifelong learning.}
  \end{itemize}
}

\posterbox[highlightcard, title={What Can Be Done}
]{name=cta, column=2, between=row14 and bottom}{
  \fontsize{25}{34}\selectfont
  \colorbox{primary!18}{\parbox{0.94\linewidth}{%
    \centering\fontsize{24}{30}\selectfont
    UNICEF's education work supports \textbf{SDG 4}: inclusive and equitable quality education for all.
  }}

  \vspace{10pt}
  \textbf{Every investment in education is an investment in:}

  \vspace{6pt}
  \begin{itemize}[itemsep=10pt]
    \item \textbf{Peace} $\Rightarrow$ Education reduces conflict and builds stable societies.
    \item \textbf{Innovation} $\Rightarrow$ An educated generation drives progress.
    \item \textbf{Sustainable Development} $\Rightarrow$ Education lifts communities out of poverty.
  \end{itemize}

  \vspace{10pt}
  \colorbox{accent!22}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{28}{36}\selectfont\bfseries\color{accent} Together, we can ensure}\\[4pt]
    {\fontsize{32}{40}\selectfont\bfseries\color{primary} no child is left behind.}\vspace{6pt}%
  }}

  \vspace{10pt}
  {\fontsize{22}{28}\selectfont\color{textgray}\centering
  Governments, communities, organizations, and individuals -- every action counts.\par
  \textbf{Learn more: unicef.org/education}}
}

\end{tcbposter}
\end{document}

